package main

import "fmt"

func main() {
	// Integer division truncates; modulo gives the remainder.
	a, b := 7, 2
	fmt.Println("7/2 =", a/b, "7%2 =", a%b) // 3 and 1

	// For a fractional result, convert to float64 first.
	fmt.Printf("7/2 as float = %.1f\n", float64(a)/float64(b)) // 3.5

	// Comparison operators yield bool.
	fmt.Println("a > b:", a > b, "a == b:", a == b)

	// Short-circuit: the right side is skipped if the left is false,
	// so we never index out of range when len is 0.
	nums := []int{}
	if len(nums) > 0 && nums[0] == 1 { // nums[0] never evaluated here
		fmt.Println("first is one")
	} else {
		fmt.Println("empty or first != 1")
	}

	// ++ is a statement, used on its own line.
	count := 0
	count++
	fmt.Println("count:", count)
}
